'use client';

// The quiet marks on a comment every product's thread draws the same way (docs/specs/024-agents/agent-presence.md
// "Comments" in each canvas product, liveplanner's items.md "Generated by AI"): Generated by AI above an agent's
// comment, and "· Edited" beside the time of one whose text changed after it was posted.

import { lucideGlyph } from '@liveworkspace/ui';
import { lucideSparkles } from '@liveworkspace/icons/lucide';

const AiIcon = lucideGlyph(lucideSparkles, 11);

/** The Generated by AI pill above an agent's comment (`ai: true`, stamped by the server). */
export function AiCommentMark() {
  return (
    <p
      data-comment-ai=""
      className="mt-0.5 inline-flex items-center gap-1 rounded-full bg-violet-50 px-1.5 py-px text-[10px] font-medium text-violet-700 dark:bg-violet-500/15 dark:text-violet-300"
    >
      <AiIcon aria-hidden />
      Generated by AI
    </p>
  );
}

/** "· Edited" beside a comment's time, once its author changed its text. */
export function EditedCommentMark() {
  return (
    <span
      data-comment-edited=""
      className="shrink-0 text-[11px] text-slate-500 dark:text-slate-400"
    >
      · Edited
    </span>
  );
}
